(()=>{'use strict';const A=RepoAccount,$=s=>document.querySelector(s),dialog=$('#report-listing-dialog');if(!dialog)return;let project,identity,epoch=0;dialog.querySelector('.close').onclick=()=>dialog.close();document.addEventListener('click',async e=>{const b=e.target.closest('[data-report-listing]');if(!b)return;if(!A.user?.githubConnected){window.openAccount?.();return}if(A.legal.required){location.href='/legal.html';return}project=b.dataset.reportListing;identity=A.user.id;epoch++;$('#report-listing-project').textContent=project;$('#report-listing-explanation').value='';$('#report-listing-message').textContent='';$('#report-listing-send').disabled=false;dialog.showModal();try{const legal=await A.request('/api/auth?action=legal');if(identity!==A.user?.id)return;const contact=$('#report-listing-contact');contact.textContent=legal.contactEmail?'For privacy or legal requests, you can also contact '+legal.contactEmail+'.':'Privacy and legal contact information is available in our Privacy Policy.'}catch{}});$('#report-listing-form').onsubmit=async e=>{e.preventDefault();const token=epoch;if(identity!==A.user?.id){dialog.close();return}$('#report-listing-send').disabled=true;try{const data=await A.request('/api/editorial?action=report',{method:'POST',body:JSON.stringify({id:project,reason:$('#report-listing-reason').value,explanation:$('#report-listing-explanation').value})});if(token!==epoch||identity!==A.user?.id)return;$('#report-listing-message').textContent=data.duplicate?'An open report already exists for this issue. It is awaiting review.':'Report received. An administrator will review it.'}catch(err){if(token===epoch&&identity===A.user?.id){$('#report-listing-message').textContent=err.message;$('#report-listing-send').disabled=false}}};window.addEventListener('reposhelf-account',()=>{if(identity&&identity!==A.user?.id){epoch++;project=null;identity=null;dialog.close();$('#report-listing-explanation').value='';$('#report-listing-message').textContent=''}})})();
